//! `librosa` spectral core references (fixture `spectrum.json`, generated by
//! `cases/spectrum.py`): windows, mel filterbanks, unit conversions, STFT/ISTFT,
//! dB scaling, melspectrogram, MFCC, delta, stack_memory, window_sumsquare.
//!
//! Tolerances are peak-relative (`|a - e| <= rtol * max|e|`, see
//! `common::assert_close`). Our algorithms follow librosa/SciPy operation by
//! operation; the remaining differences are
//! - the FFT (pocketfft in SciPy vs realfft/rustfft here: different butterfly
//!   orders, ~1e-16 relative to the peak per transform),
//! - matrix products (BLAS/einsum vs ndarray's matrixmultiply summation order),
//! - libm `cos`/`exp`/`log` ulp differences.
//!
//! Each tolerance below states which of these applies. Measured errors are
//! printed with `--nocapture`.

use std::num::NonZeroUsize;

use audio_samples::operations::filterbanks::{
    MelFilterNorm, MelFilterbankConfig, MelScale, Window, get_window, mel_filterbank,
    window_bandwidth, window_sumsquare,
};
use audio_samples::operations::spectrum::{
    AudioSpectrum, DbConfig, DbReference, DctNorm, DctType, DeltaConfig, DeltaMode,
    MelSpectrogramConfig, MfccConfig, StftConfig, StftPadMode, amplitude_to_db, db_to_amplitude,
    db_to_power, delta, frame, istft, power_to_db, stack_memory, stft,
};
use audio_samples::utils::audio_math::{
    frames_to_samples_slice, frames_to_time_with_offset_slice, hz_to_mel_with_scale,
    mel_frequencies_with_scale, mel_to_hz_with_scale, samples_to_frames_slice,
    time_to_frames_floor_slice, time_to_samples_slice,
};
use audio_samples::{AudioSamples, nzu};
use ndarray::{Array2, Array3, s};
use num_complex::Complex;
use serde_json::Value;

use crate::common::{
    arr1, arr2, arr3, assert_close, carr2, carr3, errors, f64s, load, mono, signal, sr, stereo,
};

fn fixture() -> &'static Value {
    static F: std::sync::OnceLock<Value> = std::sync::OnceLock::new();
    F.get_or_init(|| load("spectrum"))
}

fn nz(v: &Value) -> NonZeroUsize {
    NonZeroUsize::new(v.as_u64().expect("integer") as usize).expect("non-zero")
}

fn ints(v: &Value) -> Vec<i64> {
    v.as_array()
        .expect("array")
        .iter()
        .map(|x| x.as_i64().expect("integer"))
        .collect()
}

/// Assert and print the measured agreement.
#[track_caller]
fn check<'a>(
    what: &str,
    actual: impl IntoIterator<Item = &'a f64> + Clone,
    expected: impl IntoIterator<Item = &'a f64> + Clone,
    rtol: f64,
) {
    let (abs, rel) = errors(actual.clone(), expected.clone());
    eprintln!("{what:<40} max abs {abs:.3e}  peak-rel {rel:.3e}  (rtol {rtol:e})");
    assert_close(what, actual, expected, rtol, 0.0);
}

/// Complex comparison: real and imaginary parts concatenated, so the peak is the
/// largest component of either.
#[track_caller]
fn check_complex<D: ndarray::Dimension>(
    what: &str,
    actual: &ndarray::Array<Complex<f64>, D>,
    expected: &ndarray::Array<Complex<f64>, D>,
    rtol: f64,
) {
    assert_eq!(actual.shape(), expected.shape(), "{what}: shape");
    let flat = |a: &ndarray::Array<Complex<f64>, D>| -> Vec<f64> {
        a.iter()
            .map(|z| z.re)
            .chain(a.iter().map(|z| z.im))
            .collect()
    };
    check(what, &flat(actual), &flat(expected), rtol);
}

fn window_from_name(name: &str) -> Window {
    match name {
        "hann" => Window::Hann,
        "hamming" => Window::Hamming,
        "blackman" => Window::Blackman,
        "blackmanharris" => Window::BlackmanHarris,
        "boxcar" => Window::Rectangular,
        "bartlett" => Window::Bartlett,
        "triang" => Window::Triangular,
        "kaiser" => Window::Kaiser { beta: 8.6 },
        "gaussian" => Window::Gaussian { std: 7.0 },
        other => panic!("unknown window {other}"),
    }
}

fn stft_config(params: &Value) -> StftConfig {
    let mut cfg = StftConfig::default();
    if let Some(v) = params.get("n_fft") {
        cfg.n_fft = nz(v);
    }
    if let Some(v) = params.get("hop_length") {
        cfg.hop_length = Some(nz(v));
    }
    if let Some(v) = params.get("win_length") {
        cfg.win_length = Some(nz(v));
    }
    if let Some(v) = params.get("window") {
        cfg.window = window_from_name(v.as_str().unwrap());
    }
    if let Some(v) = params.get("center") {
        cfg.center = v.as_bool().unwrap();
    }
    if let Some(v) = params.get("pad_mode") {
        cfg.pad_mode = match v.as_str().unwrap() {
            "reflect" => StftPadMode::Reflect,
            "edge" => StftPadMode::Edge,
            "constant" => StftPadMode::Constant,
            other => panic!("pad mode {other}"),
        };
    }
    cfg
}

#[test]
fn windows() {
    // Same formulas as SciPy term by term; only libm cos/exp/sqrt ulps differ.
    for (key, expected) in fixture()["windows"].as_object().unwrap() {
        let parts: Vec<&str> = key.split('_').collect();
        let w = window_from_name(parts[0]);
        let n: usize = parts[1].parse().unwrap();
        let periodic = parts[2] == "periodic";
        let actual = get_window(&w, n, periodic).unwrap();
        check(
            &format!("get_window {key}"),
            &actual,
            &arr1(expected),
            1e-14,
        );
    }
    for (name, expected) in fixture()["window_bandwidth"].as_object().unwrap() {
        let bw = window_bandwidth(&window_from_name(name), nzu!(1000)).unwrap();
        // Sums of 1000 terms; numpy uses pairwise summation, we sum sequentially.
        check(
            &format!("window_bandwidth {name}"),
            &[bw],
            &[expected["formula"].as_f64().unwrap()],
            1e-13,
        );
        // librosa's own return value comes from a precomputed table (documented
        // difference); it agrees with the n=1000 formula to ~1e-4.
        check(
            &format!("window_bandwidth {name} vs librosa table"),
            &[bw],
            &[expected["table"].as_f64().unwrap()],
            1e-3,
        );
    }
}

#[test]
fn window_sumsquare_matches() {
    let f = &fixture()["window_sumsquare"];
    let step = f["step"].as_u64().unwrap() as usize;
    let a = window_sumsquare(&Window::Hann, 10, nzu!(256), Some(nzu!(800)), nzu!(1024)).unwrap();
    let a: Vec<f64> = a.iter().step_by(step).copied().collect();
    // Sums of at most 4 squared window values: round-off only.
    check(
        "window_sumsquare hann winlen",
        &a,
        &f64s(&f["hann_winlen"]),
        1e-14,
    );
    let b = window_sumsquare(&Window::Hamming, 6, nzu!(512), None, nzu!(2048)).unwrap();
    let b: Vec<f64> = b.iter().step_by(step).copied().collect();
    check("window_sumsquare hamming", &b, &f64s(&f["hamming"]), 1e-14);
}

#[test]
fn mel_filterbanks() {
    for (name, case) in fixture()["mel"].as_object().unwrap() {
        let p = &case["params"];
        let norm = match &p["norm"] {
            Value::Null => MelFilterNorm::None,
            Value::String(s) if s == "slaney" => MelFilterNorm::Slaney,
            Value::String(s) if s == "inf" => MelFilterNorm::Lp(f64::INFINITY),
            v => MelFilterNorm::Lp(v.as_f64().unwrap()),
        };
        let cfg = MelFilterbankConfig {
            n_mels: nz(&p["n_mels"]),
            fmin: p["fmin"].as_f64().unwrap(),
            fmax: p["fmax"].as_f64(),
            scale: if p["htk"].as_bool().unwrap() {
                MelScale::Htk
            } else {
                MelScale::Slaney
            },
            norm,
        };
        let m = mel_filterbank(p["sr"].as_f64().unwrap(), nz(&p["n_fft"]), &cfg).unwrap();
        assert_eq!(
            m.shape(),
            &[
                case["shape"][0].as_u64().unwrap() as usize,
                case["shape"][1].as_u64().unwrap() as usize
            ]
        );
        let (rs, cs) = (
            case["row_step"].as_u64().unwrap() as usize,
            case["col_step"].as_u64().unwrap() as usize,
        );
        let sub = m.slice(s![..;rs, ..;cs]).to_owned();
        // Same arithmetic as librosa (float64 basis); mel edges go through log/exp,
        // so the ramps carry a few ulps.
        check(
            &format!("mel {name} subset"),
            &sub,
            &arr2(&case["subset"]),
            1e-12,
        );
        let sums: Vec<f64> = m.rows().into_iter().map(|r| r.sum()).collect();
        check(
            &format!("mel {name} row sums"),
            &sums,
            &f64s(&case["row_sums"]),
            1e-12,
        );
        let maxes: Vec<f64> = m
            .rows()
            .into_iter()
            .map(|r| r.fold(0.0f64, |a, &b| a.max(b)))
            .collect();
        check(
            &format!("mel {name} row max"),
            &maxes,
            &f64s(&case["row_max"]),
            1e-12,
        );
    }
}

#[test]
fn unit_conversions() {
    let f = &fixture()["convert"];
    let freqs = f64s(&f["freqs"]);
    // Identical formulas; libm log/exp/pow ulps only.
    let tol = 1e-14;
    let slaney: Vec<f64> = freqs
        .iter()
        .map(|&x| hz_to_mel_with_scale(x, MelScale::Slaney))
        .collect();
    check(
        "hz_to_mel slaney",
        &slaney,
        &f64s(&f["hz_to_mel_slaney"]),
        tol,
    );
    let htk: Vec<f64> = freqs
        .iter()
        .map(|&x| hz_to_mel_with_scale(x, MelScale::Htk))
        .collect();
    check("hz_to_mel htk", &htk, &f64s(&f["hz_to_mel_htk"]), tol);
    let m: Vec<f64> = f64s(&f["mels_htk_in"])
        .iter()
        .map(|&x| mel_to_hz_with_scale(x, MelScale::Htk))
        .collect();
    check("mel_to_hz htk", &m, &f64s(&f["mel_to_hz_htk"]), tol);
    let m: Vec<f64> = f64s(&f["mels_slaney_in"])
        .iter()
        .map(|&x| mel_to_hz_with_scale(x, MelScale::Slaney))
        .collect();
    check("mel_to_hz slaney", &m, &f64s(&f["mel_to_hz_slaney"]), tol);
    check(
        "mel_frequencies slaney",
        &mel_frequencies_with_scale(128, 0.0, 11025.0, MelScale::Slaney),
        &f64s(&f["mel_frequencies_slaney"]),
        tol,
    );
    check(
        "mel_frequencies htk",
        &mel_frequencies_with_scale(128, 0.0, 11025.0, MelScale::Htk),
        &f64s(&f["mel_frequencies_htk"]),
        tol,
    );
    check(
        "mel_frequencies 40 slaney",
        &mel_frequencies_with_scale(40, 133.0, 6854.0, MelScale::Slaney),
        &f64s(&f["mel_frequencies_40_slaney"]),
        tol,
    );
    check(
        "mel_frequencies 40 htk",
        &mel_frequencies_with_scale(40, 133.0, 6854.0, MelScale::Htk),
        &f64s(&f["mel_frequencies_40_htk"]),
        tol,
    );

    // Integer conversions must match exactly.
    let srf = sr() as f64;
    let times = f64s(&f["times"]);
    assert_eq!(
        time_to_frames_floor_slice(&times, srf, nzu!(512), None),
        ints(&f["time_to_frames"])
    );
    assert_eq!(
        time_to_frames_floor_slice(&times, srf, nzu!(512), Some(2048)),
        ints(&f["time_to_frames_nfft"])
    );
    assert_eq!(
        time_to_samples_slice(&times, srf),
        ints(&f["time_to_samples"])
    );
    assert_eq!(
        samples_to_frames_slice(&ints(&f["samples"]), nzu!(512), Some(2047)),
        ints(&f["samples_to_frames"])
    );
    let frames = ints(&f["frames"]);
    assert_eq!(
        frames_to_samples_slice(&frames, nzu!(300), None),
        ints(&f["frames_to_samples"])
    );
    // int / float division: exact.
    let t = frames_to_time_with_offset_slice(&frames, srf, nzu!(512), Some(2048));
    assert_eq!(t, f64s(&f["frames_to_time_nfft"]));
}

#[test]
fn stft_cases() {
    let x = mono("mix");
    for (name, case) in fixture()["stft"].as_object().unwrap() {
        let cfg = stft_config(&case["params"]);
        let d = x.stft_matrix(&cfg).unwrap();
        let shape: Vec<usize> = case["shape"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_u64().unwrap() as usize)
            .collect();
        assert_eq!(&d.shape()[1..], &shape[..], "stft {name} shape");
        let (bs, fs) = (
            case["bin_step"].as_u64().unwrap() as usize,
            case["frame_step"].as_u64().unwrap() as usize,
        );
        let sub = d.slice(s![0, ..;bs, ..;fs]).to_owned();
        // Different FFT implementations (pocketfft vs realfft): ~1e-16 x peak per bin.
        check_complex(
            &format!("stft {name}"),
            &sub,
            &carr2(&case["subset"]),
            1e-13,
        );
    }
    let st = &fixture()["stft_stereo"];
    let d = stereo().stft_matrix(&StftConfig::default()).unwrap();
    let shape: Vec<usize> = st["shape"]
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_u64().unwrap() as usize)
        .collect();
    assert_eq!(d.shape(), &shape[..]);
    let (bs, fs) = (
        st["bin_step"].as_u64().unwrap() as usize,
        st["frame_step"].as_u64().unwrap() as usize,
    );
    let sub = d.slice(s![.., ..;bs, ..;fs]).to_owned();
    check_complex("stft stereo", &sub, &carr3(&st["subset"]), 1e-13);
}

#[test]
fn istft_cases() {
    let f = &fixture()["istft"];
    let short: Vec<f64> = signal("mix")[..3000].to_vec();
    let x = Array2::from_shape_vec((1, short.len()), short.clone()).unwrap();
    let gain = |k: usize| 1.0 / (1.0 + k as f64 / 100.0);
    let apply_gain = |mut d: Array3<Complex<f64>>| {
        for ((_, k, _), z) in d.indexed_iter_mut() {
            *z *= gain(k);
        }
        d
    };
    let cfg = StftConfig::default();
    let dm = apply_gain(stft(x.view(), &cfg).unwrap());
    // Inverse FFT + overlap-add + division by the window envelope: FFT round-off only.
    let tol = 1e-12;
    let y = istft(dm.view(), &cfg, Some(short.len())).unwrap();
    let y2: Vec<f64> = y.iter().step_by(2).copied().collect();
    check(
        "istft length given",
        &y2,
        &f64s(&f["length_given_step2"]),
        tol,
    );
    let y = istft(dm.view(), &cfg, None).unwrap();
    assert_eq!(y.ncols() as u64, f["no_length_len"].as_u64().unwrap());
    let y4: Vec<f64> = y.iter().step_by(4).copied().collect();
    check("istft no length", &y4, &f64s(&f["no_length_step4"]), tol);
    let longer_len = f["longer_len"].as_u64().unwrap() as usize;
    let y = istft(dm.view(), &cfg, Some(longer_len)).unwrap();
    let tail = y.slice(s![0, longer_len - 1500..]).to_owned();
    // This tail includes the last reconstructed samples, where the window envelope
    // falls towards zero and dividing by it amplifies FFT round-off (~2e-12 measured).
    check(
        "istft longer (zero-padded tail)",
        &tail,
        &arr1(&f["longer"]),
        1e-10,
    );

    let cfg2 = StftConfig::default()
        .with_n_fft(nzu!(1024))
        .with_hop_length(Some(nzu!(256)))
        .with_win_length(Some(nzu!(800)))
        .with_center(false);
    let d2 = apply_gain(stft(x.view(), &cfg2).unwrap());
    let y = istft(d2.view(), &cfg2, None).unwrap();
    let y2: Vec<f64> = y.iter().step_by(2).copied().collect();
    // Uncentred: the first/last samples sit where the window envelope is tiny, so
    // FFT round-off is amplified there (1.5e-12 measured); interior samples agree to 1e-15.
    check(
        "istft uncentred win_length",
        &y2,
        &f64s(&f["nocenter_winlen_step2"]),
        1e-10,
    );

    // Trait form returns audio.
    let audio = AudioSamples::<f64>::istft_matrix(
        &dm,
        &cfg,
        audio_samples::sample_rate!(22050),
        NonZeroUsize::new(3000),
    )
    .unwrap();
    assert_eq!(audio.samples_per_channel().get(), 3000);
}

#[test]
fn melspectrogram_cases() {
    let f = &fixture()["melspectrogram"];
    let rs = f["row_step"].as_u64().unwrap() as usize;
    let x = mono("mix");
    let m = x.melspectrogram(&MelSpectrogramConfig::default()).unwrap();
    let sub = m.slice(s![0, ..;rs, ..]).to_owned();
    // STFT round-off plus a 1025-term matrix product (BLAS vs matrixmultiply order).
    check("melspectrogram default", &sub, &arr2(&f["default"]), 1e-12);
    // librosa's default float32 mel basis: ~6e-8 relative rounding of the weights.
    check(
        "melspectrogram vs float32 basis",
        &sub,
        &arr2(&f["default_float32_basis"]),
        1e-6,
    );

    let cfg = MelSpectrogramConfig::default().with_power(1.0).with_mel(
        MelFilterbankConfig::new()
            .with_n_mels(nzu!(64))
            .with_fmin(50.0)
            .with_fmax(Some(8000.0))
            .with_scale(MelScale::Htk),
    );
    let m = x.melspectrogram(&cfg).unwrap();
    let sub = m.slice(s![0, ..;rs, ..]).to_owned();
    check(
        "melspectrogram htk power 1",
        &sub,
        &arr2(&f["htk_power1"]),
        1e-12,
    );

    let srs = f["stereo_row_step"].as_u64().unwrap() as usize;
    let m = stereo()
        .melspectrogram(&MelSpectrogramConfig::default())
        .unwrap();
    let sub = m.slice(s![.., ..;srs, ..]).to_owned();
    check("melspectrogram stereo", &sub, &arr3(&f["stereo"]), 1e-12);
}

#[test]
fn db_conversions() {
    let f = &fixture()["db"];
    // Inputs are librosa's exact inputs (stored); log10 ulps only. dB values are
    // O(100), so 1e-12 relative to the peak is ~1e-10 dB.
    let tol = 1e-12;
    let mel_in = arr2(&fixture()["melspectrogram"]["default"]);
    let cfg = DbConfig::librosa_power();
    check(
        "power_to_db default",
        &power_to_db(&mel_in, &cfg).unwrap(),
        &arr2(&f["power_default"]),
        tol,
    );
    let max_cfg = cfg.clone().with_reference(DbReference::Max);
    check(
        "power_to_db ref=max",
        &power_to_db(&mel_in, &max_cfg).unwrap(),
        &arr2(&f["power_ref_max"]),
        tol,
    );
    check(
        "power_to_db top_db=None",
        &power_to_db(&mel_in, &cfg.with_top_db(None)).unwrap(),
        &arr2(&f["power_no_top_db"]),
        tol,
    );
    // Stereo: reference max and top_db are per channel (axes="auto").
    let srs = f["power_stereo_ref_max_row_step"].as_u64().unwrap() as usize;
    let m = stereo()
        .melspectrogram(&MelSpectrogramConfig::default())
        .unwrap();
    let db = power_to_db(&m, &max_cfg).unwrap();
    // Input computed here (melspectrogram round-off ~1e-14 rel) -> dB abs error ~1e-13.
    check(
        "power_to_db stereo ref=max",
        &db.slice(s![.., ..;srs, ..]).to_owned(),
        &arr3(&f["power_stereo_ref_max"]),
        tol,
    );

    let mag = carr2(&fixture()["stft"]["default"]["subset"]).mapv(|z| z.norm());
    check(
        "amplitude_to_db ref=max",
        &amplitude_to_db(
            &mag,
            &DbConfig::librosa_amplitude().with_reference(DbReference::Max),
        )
        .unwrap(),
        &arr2(&f["amplitude_ref_max"]),
        tol,
    );
    check(
        "amplitude_to_db default",
        &amplitude_to_db(&mag, &DbConfig::librosa_amplitude()).unwrap(),
        &arr2(&f["amplitude_default"]),
        tol,
    );
    let db_in = arr1(&f["db_in"]);
    check(
        "db_to_power ref=2",
        &db_to_power(&db_in, 2.0),
        &arr1(&f["db_to_power_ref2"]),
        1e-14,
    );
    check(
        "db_to_amplitude ref=2",
        &db_to_amplitude(&db_in, 2.0),
        &arr1(&f["db_to_amplitude_ref2"]),
        1e-14,
    );
}

#[test]
fn mfcc_cases() {
    let f = &fixture()["mfcc"];
    let x = mono("mix");
    // MFCC = DCT of dB values: dB errors are absolute (~1e-12 dB for ~1e-14 relative
    // mel error), and the DCT is a direct matrix product here vs an FFT-based DCT in
    // SciPy. Bins floored by top_db agree exactly. 1e-11 relative to the peak.
    let tol = 1e-11;
    let cases: Vec<(&str, MfccConfig)> = vec![
        ("default", MfccConfig::librosa()),
        ("lifter22", MfccConfig::librosa().with_lifter(22.0)),
        ("dct3", MfccConfig::librosa().with_dct_type(DctType::Three)),
        ("dct1", MfccConfig::librosa().with_dct_type(DctType::One)),
        (
            "norm_none",
            MfccConfig::librosa().with_dct_norm(DctNorm::Unnormalized),
        ),
        (
            "htk_13_40",
            MfccConfig::librosa()
                .with_n_mfcc(nzu!(13))
                .with_mel_spectrogram(
                    MelSpectrogramConfig::default().with_mel(
                        MelFilterbankConfig::new()
                            .with_n_mels(nzu!(40))
                            .with_scale(MelScale::Htk),
                    ),
                ),
        ),
    ];
    for (name, cfg) in cases {
        let m = x.mfcc_frames(&cfg).unwrap();
        check(
            &format!("mfcc {name}"),
            &m.index_axis(ndarray::Axis(0), 0).to_owned(),
            &arr2(&f[name]),
            tol,
        );
    }
    let m = stereo().mfcc_frames(&MfccConfig::librosa()).unwrap();
    check("mfcc stereo", &m, &arr3(&f["stereo"]), tol);
}

#[test]
fn delta_and_stack_memory() {
    let mfcc = arr2(&fixture()["mfcc"]["default"]);
    let f = &fixture()["delta"];
    // Exact input. SciPy fits with lstsq/polyfit, we use a scaled normal-equation
    // solve; both are exact up to a few ulps of the (small-integer) weights.
    let tol = 1e-12;
    let cases: Vec<(&str, DeltaConfig)> = vec![
        ("order1", DeltaConfig::default()),
        ("order2", DeltaConfig::default().with_order(2)),
        ("width5", DeltaConfig::default().with_width(5)),
        (
            "nearest",
            DeltaConfig::default().with_mode(DeltaMode::Nearest),
        ),
        (
            "mirror_w7_o2",
            DeltaConfig::default()
                .with_width(7)
                .with_order(2)
                .with_mode(DeltaMode::Mirror),
        ),
        ("wrap", DeltaConfig::default().with_mode(DeltaMode::Wrap)),
        (
            "constant",
            DeltaConfig::default().with_mode(DeltaMode::Constant),
        ),
        ("axis0", DeltaConfig::default().with_axis(0).with_width(5)),
    ];
    for (name, cfg) in cases {
        check(
            &format!("delta {name}"),
            &delta(&mfcc, &cfg).unwrap(),
            &arr2(&f[name]),
            tol,
        );
    }
    let top = mfcc.slice(s![..5, ..]).to_owned();
    let sm = &fixture()["stack_memory"];
    // Pure copies: exact.
    assert_eq!(stack_memory(&top, nzu!(3), 2).unwrap(), arr2(&sm["n3_d2"]));
    assert_eq!(
        stack_memory(&top, nzu!(2), -1).unwrap(),
        arr2(&sm["n2_dm1"])
    );

    let fr = frame(&signal("mix")[..3000], nzu!(512), nzu!(256)).unwrap();
    assert_eq!(
        fr.slice(s![..;8, ..;3]).to_owned(),
        arr2(&fixture()["frame"]["frames"])
    );
}
